export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

/**
 * ⛔ REACH WAS A NUMBER ANYONE COULD TYPE, AND IT IS THE THING BEING SOLD.
 *
 * MARKET.md §3 promotes Reach to its own board column as the advertiser's receipt — the
 * quoted offer is "you pay, you appear, people click". Measured against the running site on
 * 2026-08-26: forty unauthenticated GETs of /out/thecompound.tech from one process took reach
 * from 0 to 40 and wrote forty ledger rows. Nothing refused one, and nothing could — there
 * was no notion of WHO clicked, so every hit was a new visitor by definition.
 *
 * A competitor inflating a rival's Reach is not even the worst case; a product inflating its
 * OWN is, because the number is what the next buyer is shown as proof the board works.
 *
 * So a click is now attributed to a client. The address is hashed, never stored: this is a
 * counter, it has no business keeping a visitor log, and a hash is all a dedup needs. The
 * key is the same secret the owner and pending cookies are signed with — already required
 * for the product to run at all, and never sent to a client.
 */
function clientHash(req: Request): string | null {
  const secret = process.env.STRIPE_SECRET_KEY;
  if (!secret) return null;
  const h = req.headers;
  // Only use the address headers written by the deployment edge. The leftmost
  // X-Forwarded-For value is caller-controlled and let one client mint a new
  // dedup identity simply by changing a request header.
  const ip = h.get('cf-connecting-ip') || h.get('x-real-ip');
  if (!ip) return null;
  // The user-agent joins the key so two people behind one NAT are not one clicker.
  return createHmac('sha256', secret)
    .update(`click:${ip}:${h.get('user-agent') ?? ''}`)
    .digest('base64url').slice(0, 32);
}

