const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
const publishable = process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;

let readClient: SupabaseClient | null = null;

/** null when the project is not configured — every caller falls back to derived data. */
export function supabaseRead(): SupabaseClient | null {
  if (!url || !publishable) return null;
  if (!readClient) readClient = createClient(url, publishable, { auth: { persistSession: false } });
  return readClient;
}

/** Server-only. Throws rather than silently falling back — a mint must never be faked. */
export function supabaseWrite(): SupabaseClient {
  const service = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !service) {
    throw new Error(
      'SUPABASE_SERVICE_ROLE_KEY is not set. Minting writes to the board and must not run ' +
      'against a client key. Add it to .env.local before opening packs for real.',
    );
  }
  return createClient(url, service, { auth: { persistSession: false } });
}

